<?php if($hasSpecifications):?><div class="tab-panel <?=$firstTab==='specs'?'active':''?>" data-panel="specs"><div class="table-scroll"><?php if($lovable):?><table class="spec-table"><thead><tr><th>Modello</th><th>Raffr. (kW)</th><th>SEER</th><th>Risc. (kW)</th><th>SCOP</th><th>Codice UI</th><th>Codice UE</th></tr></thead><tbody><?php foreach($lovable['specs'] as $i=>$s):$pr=$lovable['prices'][$i]??[];?><tr><td><strong><?=e($s['model'])?></strong></td><td><?=$s['cooling_kw']?></td><td><?=$s['seer']?> (<?=e($s['seer_class'])?>)</td><td><?=$s['heating_kw']?></td><td><?=$s['scop']?> (<?=e($s['scop_class'])?>)</td><td><?=e($pr['ui_code']??'—')?></td><td><?=e($pr['ue_code']??'—')?></td></tr><?php endforeach;?></tbody></table><p><small>Valori SEER e SCOP misurati secondo la norma armonizzata EN14825. Per il listino prezzi consulta il PDF ufficiale.</small></p><?php else:?><table class="spec-table"><thead><tr><th>Dato tecnico</th><th>Valore</th></tr></thead><tbody><?php foreach($specifications as $s):?><tr><td><strong><?=e($s['specification_key'])?></strong></td><td><?=e($s['specification_value'])?></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></div><?php endif;?>
<?php if($hasAccessories):?><div class="tab-panel <?=$firstTab==='accessories'?'active':''?>" data-panel="accessories"><div class="table-scroll"><table class="spec-table"><thead><tr><th>Codice</th><th>Accessorio</th><th>Descrizione</th></tr></thead><tbody><?php if($lovable):foreach($lovable['accessories'] as $a):$inc=stripos($a['price'],'incluso')!==false;?><tr><td><?=e($a['code'])?></td><td><?=e($a['description'])?></td><td><span class="availability <?=$inc?'included':''?>"><?=$inc?'Incluso':'Opzionale'?></span></td></tr><?php endforeach;else:foreach($accessories as $a):?><tr><td><?=e($a['code']?:'—')?></td><td><strong><?=e($a['name'])?></strong></td><td><?=e($a['description']?:'—')?></td></tr><?php endforeach;endif;?></tbody></table></div></div><?php endif;?>
<div class="tab-panel" data-panel="documents"><p>Consulta qui sotto schede tecniche, tabelle rese, detrazioni, conto termico e manuali.</p></div></div><?php endif;?>
<div class="documents-title" id="documenti"><h2>Documenti PDF</h2><span><?=$documentTotal?> file disponibili</span></div><div class="document-groups"><?php foreach($documentGroups as $groupName=>$documents):?><section class="doc-group"><div class="doc-group-head"><h3><?=e((string)$groupName)?></h3><span class="doc-count"><?=count($documents)?> file</span></div><div class="doc-list"><?php foreach($documents as $d):?><a class="doc" href="/idemaclima/documento/<?=(int)$d['id']?>/download" target="_blank" rel="noopener"><span><strong><?=e($d['title'])?></strong><?php if(!empty($d['document_year'])||!empty($d['revision'])):?><small><?=!empty($d['document_year'])?(int)$d['document_year']:''?><?=!empty($d['revision'])?' · Rev. '.e($d['revision']):''?></small><?php endif;?></span><span class="doc-open">Apri ↗</span></a><?php endforeach;?></div></section><?php endforeach;?></div></div></section>
<?php if($lovable):$cool=array_column($lovable['specs'],'cooling_kw');$heat=array_column($lovable['specs'],'heating_kw');?><div id="lovable-product-data" hidden data-cool-min="<?=min($cool)?>" data-cool-max="<?=max($cool)?>" data-heat-min="<?=min($heat)?>" data-heat-max="<?=max($heat)?>" data-warranty="<?=e($lovable['warranty'])?>"></div>
